script:
(function () {
  'use strict';
  // ---- Tax rule (2026) --------------------------------------------------------------------
  // Additional tax on early distributions from a nonqualified annuity: 10% of the taxable part
  // (the gain) when taken before age 59 1/2. Source: IRC section 72(q); IRS Publication 575.
  // Applied here when the age at cash-out is below 59.5.
  var EARLY_TAX = 0.10;
  var EARLY_AGE = 59.5;
  // -----------------------------------------------------------------------------------------
  // No-surrender-charge variable annuity vs a taxable account, compounded yearly. The starting
  // deposit and each yearly addition go in at the start of the year (both in year 1), with
  // after-tax money in both accounts.
  // Annuity: value = value x (1 + return) - value x total yearly cost. With no surrender charge it
  //   can be cashed out at the end of any year: the gain over deposits is taxed at the ordinary
  //   rate, plus 10% of the gain if the age then is under 59 1/2.
  // Taxable account: value = value x (1 + return - fund expense); the chosen share of each year's
  //   positive growth is paid out (dividends, fund distributions), taxed that year at the
  //   distribution rate and reinvested (raising the cost basis); the rest of the gain is taxed at
  //   the capital gains rate on the final sale.
  // Break-even holding period = the first year from which the annuity's after-tax cash-out value
  //   matches or beats the taxable account's in every later year shown (up to 60 years or age 100).
  // Break-even cost = the yearly annuity cost (found by bisection) at which both are equal after
  //   tax at your withdrawal age.
  // Verified (Node, scratchpad slc5/vn.test.js): $100,000 at 7% less a 0.5% cost for 15 years =
  //   100,000 x 1.065^15 = $257,184.10; after 22% tax on the gain -> $222,603.60; taxable with 0%
  //   paid out, no fund fee, 15% capital gains = 275,903.15 - 175,903.15 x 0.15 = $249,517.68;
  //   100% paid out at 20% and no fee grows at 5.6% -> 100,000 x 1.056^15 = $226,442.93; with equal
  //   tax rates and no costs the annuity is never behind; at the break-even cost (0.7957% over 20
  //   years when all growth is taxed yearly at 24%) the two after-tax values match to the cent;
  //   the 10% additional tax applies at age 59 and not at 60 (the 59 1/2 rule).
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var COSTS = [0.0010, 0.0025, 0.0050, 0.0075, 0.0100, 0.0125, 0.0150, 0.0200];

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }
  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function project(p, cost, years) {
    var va = 0, basis = 0, tx = 0, txBasis = 0, rows = [];
    for (var k = 1; k <= years; k++) {
      var add = (k === 1 ? p.start : 0) + p.contrib;
      va += add; basis += add; tx += add; txBasis += add;
      va = Math.max(0, va * (1 + p.rate - cost));
      var growth = tx * (p.rate - p.txFee);
      var paidOut = Math.max(0, growth) * p.payout, taxNow = paidOut * p.divTax;
      tx = Math.max(0, tx + growth - taxNow);
      txBasis += paidOut - taxNow;
      var age = p.age + k, gain = Math.max(0, va - basis);
      var vaNet = va - gain * p.ordTax - (age < EARLY_AGE ? gain * EARLY_TAX : 0);
      var txNet = tx - Math.max(0, tx - txBasis) * p.cgTax;
      rows.push({ year: k, age: age, va: va, basis: basis, vaNet: vaNet, tx: tx, txNet: txNet });
    }
    return rows;
  }

  // First year from which the annuity is never behind again (0 = never within the rows).
  function breakEven(rows) {
    var from = 0;
    for (var i = rows.length - 1; i >= 0 && rows[i].vaNet >= rows[i].txNet - 0.005; i--) from = rows[i].year;
    return from;
  }

  // Yearly annuity cost that ties the two after tax after `years`; null if even 0% cost trails.
  function breakEvenCost(p, years) {
    function diff(c) { var r = project(p, c, years)[years - 1]; return r.vaNet - r.txNet; }
    if (diff(0) < 0) return null;
    var lo = 0, hi = 0.10;
    if (diff(hi) > 0) return hi;
    for (var t = 0; t < 80; t++) { var mid = (lo + hi) / 2; if (diff(mid) > 0) lo = mid; else hi = mid; }
    return (lo + hi) / 2;
  }

  function clearBody(id) {
    var body = el(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }
  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) { var td = document.createElement('td'); td.textContent = text; tr.appendChild(td); });
    body.appendChild(tr);
  }
  function signed(v) { return (v < 0 ? '−' : '+') + money.format(Math.abs(v)); }
  function pctText(v) { return (v * 100).toFixed(2) + '%'; }

  function update() {
    var p = { start: read('vnStart', true), contrib: read('vnContrib', true), age: read('vnAge'), wAge: read('vnWithdrawAge'),
              rate: read('vnReturn'), cost: read('vnCost'), txFee: read('vnTxFee'), payout: read('vnPayout'),
              ordTax: read('vnOrdTax'), divTax: read('vnDivTax'), cgTax: read('vnCgTax') };
    var msg = '';
    if (Object.keys(p).some(function (k) { return isNaN(p[k]); })) msg = 'Fill in every field.';
    else if (p.start < 0 || p.contrib < 0 || p.start + p.contrib <= 0) msg = 'Enter a starting deposit or a yearly addition.';
    else if (p.age < 0 || p.age > 95 || p.wAge <= p.age || p.wAge > 100)
      msg = 'Enter a current age up to 95 and a later withdrawal age (up to 100).';
    else if (p.rate < -20 || p.rate > 30) msg = 'Enter a yearly return from -20% to 30%.';
    else if (p.cost < 0 || p.cost > 10 || p.txFee < 0 || p.txFee > 10) msg = 'Enter costs from 0% to 10% a year.';
    else if ([p.payout, p.ordTax, p.divTax, p.cgTax].some(function (r) { return r < 0 || r > 100; }))
      msg = 'Enter tax rates and the paid-out share from 0% to 100%.';
    var error = el('vnError');
    error.hidden = msg === '';
    if (msg) { error.textContent = msg; return; }
    p.age = Math.floor(p.age); p.wAge = Math.floor(p.wAge);
    ['rate', 'cost', 'txFee', 'payout', 'ordTax', 'divTax', 'cgTax'].forEach(function (k) { p[k] /= 100; });
    var years = p.wAge - p.age, horizon = Math.max(years, Math.min(60, 100 - p.age));

    var rows = project(p, p.cost, horizon), at = rows[years - 1], be = breakEven(rows);
    setText('vnBreakEven', be ? be + (be === 1 ? ' year' : ' years') : 'Not within ' + horizon + ' years');
    setText('vnBreakEvenNote', be ? 'Cash out at age ' + (p.age + be) + ' or later and the annuity comes out ahead.' :
      'With these figures the taxable account stays ahead.');
    setText('vnVaNet', money.format(at.vaNet));
    setText('vnTxNet', money.format(at.txNet));
    setText('vnDiff', signed(at.vaNet - at.txNet));
    var c = breakEvenCost(p, years);
    setText('vnMaxCost', c === null ? 'None – even a 0% cost trails' : (c >= 0.10 ? '10% or more' : pctText(c)) + ' a year');
    setText('vnVaValue', money.format(at.va));
    setText('vnDeposits', money.format(at.basis));
    setText('vnTxValue', money.format(at.tx));
    el('vnEarly').hidden = p.wAge >= EARLY_AGE;

    var sens = clearBody('vnSensitivity');
    COSTS.forEach(function (cost) {
      var r = project(p, cost, horizon), b = breakEven(r), w = r[years - 1];
      addRow(sens, [pctText(cost) + (Math.abs(cost - p.cost) < 1e-9 ? ' (yours)' : ''),
                    b ? b + ' yrs (age ' + (p.age + b) + ')' : 'Not within ' + horizon + ' yrs', signed(w.vaNet - w.txNet)]);
    });
    var body = clearBody('vnTable');
    rows.forEach(function (r) {
      addRow(body, [String(r.year), String(r.age), money.format(r.va), money.format(r.vaNet), money.format(r.txNet),
                    signed(r.vaNet - r.txNet)]);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('vnForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
